        if passenger.luggage_kg > limit:
            # 카운트 증가
            current = self.overcharge_tracker.get(passenger.flight_id, 0)
            self.overcharge_tracker[passenger.flight_id] = current + 1
            return "CHARGE_FEE"
        return None

